import {products,money,due,escapeHTML as esc,garmentSVG} from './catalog.js';
const $=s=>document.querySelector(s);let filter='All',current=null,selectedSize=null,bag=[],look=0,uploaded=null,generation='idle',generationTimer,toastTimer;
const looks=[products[0],products[2],products[4]];
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function open(id){const d=$(id);if(!d.open)d.showModal()}
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>b.closest('dialog').close();
for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
function art(p){return p.image?`<img src="${p.image}" alt="${esc(p.name)}">`:garmentSVG(p)}
function renderProducts(){const visible=products.filter(p=>filter==='All'||p.category===filter);$('#productCount').textContent=`${visible.length} PIECES`;$('#products').innerHTML=visible.map((p,i)=>`<button class="product-card" data-product="${p.id}" style="animation-delay:${i*50}ms" aria-label="View ${esc(p.name)}"><div class="product-art"><span class="product-tag">${p.mode==='quote'?'BESPOKE / SAMPLE':p.mode==='deposit'?'DEPOSIT PREORDER':p.availability.toUpperCase()}</span>${art(p)}<span class="product-number">${String(p.id).padStart(2,'0')} / FORM STUDY</span></div><div class="product-info"><div><h3>${esc(p.name)}</h3><p>${esc(p.category)}</p></div><span class="price">${p.mode==='quote'?'Guide ':''}${money(p.price)}</span></div></button>`).join('');$('#products').querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>showProduct(Number(b.dataset.product)))}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderProducts()});
function showProduct(id){current=products.find(p=>p.id===id);selectedSize=null;const p=current;$('#productDetails').innerHTML=`<div class="detail-layout"><div class="detail-art">${art(p)}</div><div class="detail-copy"><span class="eyebrow">${esc(p.category)} / DESIGN SAMPLE</span><h2>${esc(p.name)}</h2><div class="detail-price">${p.mode==='quote'?'Guide price · ':''}${money(p.price)}</div><p>${esc(p.description)}</p><label>Select your size</label><div class="sizes">${p.sizes.map(s=>`<button data-size="${s}" aria-pressed="false">${s}</button>`).join('')}</div><p>${esc(p.availability)} · Example dispatch: ${new Date(p.date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}</p>${p.mode==='deposit'?`<p><strong>${p.deposit}% deposit: ${money(due(p))}</strong><br>Example balance: ${money(p.price-due(p))}, due before dispatch.</p>`:''}${p.mode==='quote'?'<p>Final pricing and measurements are confirmed after consultation. No payment is collected for a quote request.</p>':''}<button class="button" id="addProduct">${p.mode==='quote'?'Request a sample quote':p.mode==='deposit'?'Preorder with deposit':'Add to bag'} ↗</button><p class="small-note">Demonstration product. Orders and payments are simulated.</p></div></div>`;$('#productDetails').querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{selectedSize=b.dataset.size;$('#productDetails').querySelectorAll('[data-size]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))})});$('#addProduct').onclick=()=>{if(!selectedSize){toast('Choose a size to continue.');return}if(p.mode==='quote'){ $('#productDialog').close();showQuote(p,selectedSize);return }const existing=bag.find(x=>x.id===p.id&&x.size===selectedSize);if(existing)existing.quantity++;else bag.push({id:p.id,size:selectedSize,quantity:1});updateBag();$('#productDialog').close();toast(`${p.name} added to your bag.`)};open('#productDialog')}
function updateBag(){const count=bag.reduce((n,x)=>n+x.quantity,0);$('#bagCount').textContent=count;$('#bagHeadingCount').textContent=count?` (${count})`:'';renderBag()}
function renderBag(){if(!bag.length){$('#bagContents').innerHTML='<p>Your next expression starts here.</p><p class="small-note">Your bag is empty.</p><button class="button" id="browse">Explore the collection ↗</button>';$('#browse').onclick=()=>{$('#bagDialog').close();$('#collection').scrollIntoView({behavior:'smooth'})};return}const total=bag.reduce((n,x)=>n+due(products.find(p=>p.id===x.id))*x.quantity,0);$('#bagContents').innerHTML=bag.map((x,i)=>{const p=products.find(p=>p.id===x.id);return `<div class="bag-row">${garmentSVG(p)}<div><h3>${esc(p.name)}</h3><p>Size ${x.size} · ${p.mode==='deposit'?p.deposit+'% deposit':'Full payment'}</p><div class="quantity"><button data-qty="${i}" data-delta="-1" aria-label="Decrease quantity of ${esc(p.name)}">−</button><span>${x.quantity}</span><button data-qty="${i}" data-delta="1" aria-label="Increase quantity of ${esc(p.name)}">+</button></div><button class="remove" data-remove="${i}">Remove</button></div><span>${money(due(p)*x.quantity)}</span></div>`}).join('')+`<div class="totals"><span>Due today</span><strong>${money(total)}</strong></div><p class="small-note">Example delivery area: Ile-Ife. Delivery fees await confirmation.<br>Deposit balances are separate from today's sample total.</p><button class="button" id="checkout">Continue to sample checkout ↗</button><p class="demo-note">No real payment will be collected.</p>`;$('#bagContents').querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.qty);bag[i].quantity+=Number(b.dataset.delta);if(bag[i].quantity<=0)bag.splice(i,1);updateBag()});$('#bagContents').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{bag.splice(Number(b.dataset.remove),1);updateBag()});$('#checkout').onclick=()=>{$('#bagDialog').close();showCheckout(total)}}
$('#bagOpen').onclick=()=>{renderBag();open('#bagDialog')};
function sampleForm(kind){return `<form id="sampleForm" class="form-fields"><label>Name<input name="name" placeholder="Sample customer" value="Sample customer" required autocomplete="off"></label><label>Email<input name="email" type="email" value="sample@example.com" required autocomplete="off"></label>${kind==='order'?'<label>Delivery address in Ile-Ife<input name="address" value="Example address, Ile-Ife" required autocomplete="off"></label>':'<label>Tell us about your occasion<textarea name="message" placeholder="Example: an evening celebration"></textarea></label>'}<p class="demo-banner">Use the sample details provided. Nothing is sent or stored; no payment details are requested.</p><button class="button" type="submit">${kind==='order'?'Simulate payment':'Preview quote request'} ↗</button></form>`}
function showCheckout(total){$('#checkoutContents').innerHTML=`<span class="eyebrow">DEMONSTRATION CHECKOUT</span><h2>Your next expression.</h2><div class="totals"><span>Sample amount due today</span><strong>${money(total)}</strong></div>${sampleForm('order')}`;$('#sampleForm').onsubmit=e=>{e.preventDefault();const balance=bag.reduce((n,x)=>{const p=products.find(p=>p.id===x.id);return n+(p.mode==='deposit'?p.price-due(p):0)*x.quantity},0);$('#checkoutContents').innerHTML=`<div class="success-icon">↗</div><span class="eyebrow">SAMPLE ORDER / COMPLETE</span><h2>A beautiful beginning.</h2><p>Your simulated order is complete. No payment was taken and no order was sent to Fenimi Fashion.</p><p>Sample amount paid: <strong>${money(total)}</strong>${balance?`<br>Sample balance before dispatch: <strong>${money(balance)}</strong>`:''}</p><button class="button" id="finish">Keep exploring ↗</button>`;bag=[];updateBag();$('#finish').onclick=()=>$('#checkoutDialog').close()};open('#checkoutDialog')}
function showQuote(p,size){$('#checkoutContents').innerHTML=`<span class="eyebrow">BESPOKE / SAMPLE REQUEST</span><h2>Made for your moment.</h2><p>${esc(p.name)} · Size ${size}<br>Illustrative guide price: ${money(p.price)}</p>${sampleForm('quote')}`;$('#sampleForm').onsubmit=e=>{e.preventDefault();$('#checkoutContents').innerHTML='<div class="success-icon">↗</div><h2>Your vision, imagined.</h2><p>This demonstrates a quote confirmation. No request was sent, and no payment was collected.</p><button class="button" id="finish">Return to the collection ↗</button>';$('#finish').onclick=()=>$('#checkoutDialog').close()};open('#checkoutDialog')}
function renderLooks(){ $('#lookButtons').innerHTML=looks.map((p,i)=>`<button data-look="${i}" class="${i===look?'active':''}" aria-pressed="${i===look}">${String(i+1).padStart(2,'0')} / ${['Column','Afterhours','Drape'][i]}</button>`).join('');$('#lookButtons').querySelectorAll('button').forEach(b=>b.onclick=()=>{look=Number(b.dataset.look);renderLooks();window.setOutfit?.(looks[look]);$('#lookLabel').textContent=`0${look+1} / ${['THE COLUMN','AFTERHOURS','THE DRAPE'][look]}`})}$('#shopLook').onclick=()=>showProduct(looks[look].id);
$('#adminOpen').onclick=$('#adminFooter').onclick=()=>open('#adminDialog');$('#adminMode').onchange=()=>{$('#depositField').hidden=$('#adminMode').value!=='deposit'};
function resetGeneration(){clearTimeout(generationTimer);generation='idle';$('#generationStatus').textContent='';$('#approve').hidden=true;$('#generate').disabled=false;$('#generate').textContent='Generate sample preview ↗'}
$('#upload').onchange=e=>{const f=e.target.files[0];resetGeneration();if(uploaded){URL.revokeObjectURL(uploaded);uploaded=null}if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>8*1024*1024){e.target.value='';$('#uploadStatus').textContent='Choose a JPG, PNG or WebP image under 8 MB.';return}uploaded=URL.createObjectURL(f);$('#uploadStatus').textContent=`${f.name} · local preview ready`};
$('#generate').onclick=()=>{if(!uploaded){toast('Choose a sample product photograph first.');return}generation='processing';$('#generate').disabled=true;$('#approve').hidden=true;$('#generationStatus').textContent='Simulated processing… building a demonstration silhouette.';const fail=$('#simulateFailure').checked;generationTimer=setTimeout(()=>{if(fail){generation='failed';$('#generationStatus').textContent='Simulated failure: the garment could not be reconstructed. Retry or publish your product with its photograph.';$('#generate').textContent='Retry sample generation ↗';$('#generate').disabled=false}else{generation='review';$('#generationStatus').innerHTML=garmentSVG({id:99,name:'Generic demonstration garment',color:'#444',type:'dress'})+'<p>Review ready: this generic sample silhouette was not generated from your photograph. In production, review the actual result before approving it.</p>';$('#approve').hidden=false;$('#generate').disabled=false}},1800)};
$('#approve').onclick=()=>{generation='approved';$('#generationStatus').textContent='Sample preview approved. This demonstrates the publishing workflow only.';$('#approve').hidden=true};
$('#adminForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),sizes=f.getAll('sizes');if(!sizes.length){toast('Select at least one available size.');return}if(generation==='processing'){toast('Wait for sample processing to finish.');return}const image=uploaded;products.push({id:Math.max(...products.map(p=>p.id))+1,name:f.get('name'),category:f.get('category'),price:Number(f.get('price')),mode:f.get('mode'),deposit:Number(f.get('deposit')),availability:f.get('availability'),date:f.get('date'),description:f.get('description'),sizes,color:'#555',type:'shirt',image});uploaded=null;filter='All';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='All'));renderProducts();e.target.reset();$('#depositField').hidden=true;$('#uploadStatus').textContent='';resetGeneration();$('#adminStatus').textContent='Sample product added to the collection for this session. No live product was published.';toast('Sample product added to the collection.')};
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.section-heading,.atelier-copy,.story').forEach(e=>{e.classList.add('reveal');observer.observe(e)});
renderProducts();renderLooks();updateBag();
import('./scene.js').catch(()=>{$('#sceneFallback').hidden=false;$('#rotateToggle').disabled=true;$('#rotateLeft').disabled=true;$('#rotateRight').disabled=true});
